We added support for multi kernel for python codegen but not c++ codegen. for c++ codegen it's a little trickier since we can't do the kernel picking lazily. Instead let's implement a dispatch system that looks like the below where we take the first symbolic variable and use that to find the closest hint kernel:

do {                                               \
    CUresult code = EXPR;                          \
    const char *msg;                               \
    CUresult code_get_error = cuGetErrorString(code, &msg); \
    if (code_get_error != CUDA_SUCCESS) {          \
        throw std::runtime_error(                  \
            std::string("CUDA driver error: ") +   \
            std::string("invalid error code!"));   \
    }                                              \
    if (code != CUDA_SUCCESS) {                    \
        throw std::runtime_error(                  \
            std::string("CUDA driver error: ") +   \
            std::string(msg));                     \
    }                                              \
} while (0);

using KernelFn = std::function<void(int64_t key)>;

struct KernelEntry {
    int64_t shape_key;
    KernelFn kernel;
};

static inline void dispatch_to_closest_kernel(
    const std::vector<KernelEntry>& kernels,
    int64_t key
) {
    int64_t best_distance = std::numeric_limits<int64_t>::max();
    const KernelFn* best_kernel = nullptr;

    for (const auto& entry : kernels) {
        int64_t distance = std::abs(key - entry.shape_key);
        if (distance < best_distance) {
            best_distance = distance;
            best_kernel = &entry.kernel;
        }
    }

    if (best_kernel) {
        (*best_kernel)(key);
    } else {
        throw std::runtime_error("No kernel found for dispatch");
    }
}

